package ai.home.companion;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import org.bouncycastle.crypto.params.Ed25519PrivateKeyParameters;
import org.bouncycastle.crypto.signers.Ed25519Signer;
import java.security.MessageDigest;
import java.nio.file.Files;
import java.nio.file.Path;
public class ProtocolTest {
 @Test public void productionAddressUsesSecureNarrowEndpoint(){assertEquals(Protocol.DEFAULT_URL,Protocol.validateUrl(Protocol.DEFAULT_URL));assertTrue(Protocol.DEFAULT_URL.endsWith(":8443/companion"));}
 @Test public void rejectsPlaintextCredentialsAndUrlSecrets(){for(String s:new String[]{"ws://localhost:18795","https://example.com","wss://user:pass@example.com","wss://example.com?token=abc","wss://example.com/#token","wss:///companion"}){try{Protocol.validateUrl(s);fail(s);}catch(IllegalArgumentException expected){}}}
 @Test public void bootstrapSignatureBindsActualBootstrapCredential(){Protocol.ConnectProof proof=new Protocol.ConnectProof("device","","synthetic-bootstrap",123,"nonce");assertTrue(proof.bootstrap);assertEquals("node",proof.mode);assertEquals("",proof.scopes);assertEquals("synthetic-bootstrap",proof.credential);assertEquals("v3|device|openclaw-android|node|node||123|synthetic-bootstrap|nonce|android|android",proof.payload);}
 @Test public void operatorSignatureBindsNonceDeviceAndToken(){Protocol.ConnectProof proof=new Protocol.ConnectProof("device","device-token","ignored-bootstrap",123,"nonce");assertFalse(proof.bootstrap);assertEquals("device-token",proof.credential);assertEquals("v3|device|openclaw-android|ui|operator|operator.read,operator.write,operator.approvals|123|device-token|nonce|android|android",proof.payload);assertNotEquals(proof.payload,new Protocol.ConnectProof("device","device-token","",123,"different").payload);}
 @Test public void connectionWithoutAnyCredentialIsRejected(){try{new Protocol.ConnectProof("device","","",123,"nonce");fail();}catch(IllegalArgumentException expected){}}
 @Test public void changedBootstrapTokenCannotReuseSignature(){Ed25519PrivateKeyParameters key=new Ed25519PrivateKeyParameters(hex("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60"),0);String payload=new Protocol.ConnectProof("device","","synthetic-bootstrap",123,"nonce").payload;byte[] signed=sign(key,payload);assertTrue(verify(key,payload,signed));assertFalse(verify(key,new Protocol.ConnectProof("device","","different-bootstrap",123,"nonce").payload,signed));assertFalse(verify(key,Protocol.signaturePayload("device","node","node","",123,"","nonce"),signed));}
 @Test public void exportsSyntheticProofsForInstalledGatewayInterop()throws Exception{Ed25519PrivateKeyParameters key=new Ed25519PrivateKeyParameters(hex("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60"),0);byte[] raw=key.generatePublicKey().getEncoded();StringBuilder id=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(raw))id.append(String.format("%02x",b));Path directory=Path.of("build","reports");Files.createDirectories(directory);for(boolean boot:new boolean[]{true,false}){Protocol.ConnectProof proof=new Protocol.ConnectProof(id.toString(),boot?"":"synthetic-device-token","synthetic-bootstrap",123,"synthetic-nonce");String json="{\"device\":{\"id\":\""+id+"\",\"publicKey\":\""+Protocol.b64(raw)+"\",\"signature\":\""+Protocol.b64(sign(key,proof.payload))+"\"},\"connectParams\":{\"client\":{\"id\":\"openclaw-android\",\"mode\":\""+proof.mode+"\",\"platform\":\"android\",\"deviceFamily\":\"android\"},\"auth\":{\""+(boot?"bootstrapToken":"token")+"\":\""+proof.credential+"\"}},\"role\":\""+proof.role+"\",\"scopes\":["+(boot?"":"\"operator.read\",\"operator.write\",\"operator.approvals\"")+"],\"signedAtMs\":123,\"nonce\":\"synthetic-nonce\"}";Files.write(directory.resolve(boot?"bootstrap-proof.json":"operator-proof.json"),json.getBytes(StandardCharsets.UTF_8));}}
 @Test public void base64UrlRoundtrip(){byte[] bytes=new byte[]{-1,-2,-3,0,1};String encoded=Protocol.b64(bytes);assertFalse(encoded.contains("="));assertFalse(encoded.contains("/"));assertArrayEquals(bytes,Protocol.decode(encoded));}
 @Test public void ed25519MatchesRfc8032EmptyMessageVector(){Ed25519PrivateKeyParameters key=new Ed25519PrivateKeyParameters(hex("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60"),0);assertArrayEquals(hex("d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a"),key.generatePublicKey().getEncoded());Ed25519Signer signer=new Ed25519Signer();signer.init(true,key);assertArrayEquals(hex("e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b"),signer.generateSignature());}
 private static byte[] hex(String text){byte[] b=new byte[text.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(text.substring(i*2,i*2+2),16);return b;}
 private static byte[] sign(Ed25519PrivateKeyParameters key,String payload){Ed25519Signer signer=new Ed25519Signer();signer.init(true,key);byte[] bytes=payload.getBytes(StandardCharsets.UTF_8);signer.update(bytes,0,bytes.length);return signer.generateSignature();}
 private static boolean verify(Ed25519PrivateKeyParameters key,String payload,byte[] signed){Ed25519Signer verifier=new Ed25519Signer();verifier.init(false,key.generatePublicKey());byte[] bytes=payload.getBytes(StandardCharsets.UTF_8);verifier.update(bytes,0,bytes.length);return verifier.verifySignature(signed);}
}
